INSERT INTO "announcements" ("id","title","body","created_at") VALUES (6,'New Item Alert! 🍰','Introducing our latest dessert — Portuguese Egg Tart! Freshly baked daily. Available now while stocks last.','2026-05-11 20:54:55'),
 (7,'Weekend Special Offer 🎉','Buy any 2 desserts and get 1 Buko Lychee dessert FREE! Valid this Saturday and Sunday only.','2026-05-11 20:56:05'),
 (8,'Holiday Notice 📢','We will be operating from 10AM - 8PM during the upcoming public holiday. Thank you for your support!','2026-05-11 20:57:23'),
 (9,'Limited Stock Warning ⚠️','Custard Cream Puff and Vietnamese Rolls are almost sold out today. Order yours now before they''re gone!','2026-05-11 20:58:07');
