 (20,'Vietnamese Rolls','Dessert',8.0,0,0,'https://andiksdesserts.infinityfreeapp.com/assets/vietnamese-rolls.png','Fresh rice paper rolls filled with vermicelli, prawns, lettuce and mint, served with sweet chili sauce.',0.0,0,'Tue,Wed,Fri'),
 (21,'Portuguese Egg Tart','Dessert',3.5,29,1,'https://andiksdesserts.infinityfreeapp.com/assets/portuguese-eggtart.png','Flaky golden pastry shell filled with smooth creamy egg custard, lightly caramelized on top with a silky sweet finish.',5.0,4,'Mon,Tue'),
 (23,'Nasi Ayan Penyet','Rice',6.5,25,1,'https://andiksdesserts.infinityfreeapp.com/assets/nasiayam-penyet.png','Crispy smashed fried chicken served with steamed rice, sambal belacan and fresh cucumber',0.0,0,'Tue,Wed'),
 (24,'Laksa Johor','Noodles',7.0,0,1,'https://andiksdesserts.infinityfreeapp.com/assets/laksa-johor.png','Thick spaghetti-like noodles in creamy fish-based curry gravy with herbs',0.0,0,'Mon,Wed'),
 (25,'Mihun Sup Tulang','Noodles',6.5,13,1,'https://andiksdesserts.infinityfreeapp.com/assets/mihunsup-tulang.png','Rice vermicelli in flavorful bone broth with tender beef and crispy shallots',0.0,0,'Thu,Sat'),
 (26,'Mineral Bottle','Drinks',2.0,0,1,'https://andiksdesserts.infinityfreeapp.com/assets/mineral-bottle.png','Pure and refreshing mineral water, the perfect companion to any meal.',0.0,0,'Mon,Wed'),
 (27,'Arroz caldo','Rice',12.0,23,1,'/project/uploads/menu_6a0b1ae55c5887.51665420.png','Filipino dish made of rice and chicken gruel, heavily infused with ginger, and garnished with toasted garlic, scallions, and black pepper. It is usually served with calamansi or fish sauce as condiments, as well as a hard-boiled egg.',3.66666666666667,3,'Tue,Fri'),
 (28,'Biryani rice','Rice',15.0,34,1,'/project/uploads/menu_6a0b1b0e8b3543.69885223.webp','A fragrant, warmly spiced dish made with long-grain Basmati rice, whole spices, and often ghee or saffron',0.0,0,'Mon,Thu'),
 (29,'Kimchi Fried Rice','Rice',14.0,44,1,'/project/uploads/menu_6a0b1b3467b5b8.55266428.jpg','A variety of bokkeum-bap, a popular dish in South Korea',0.0,0,'Wed,Fri'),
 (30,'Tomato rice','Rice',15.5,24,1,'/project/uploads/menu_6a0b1b8a40bc07.90426290.jpg','A simple South Indian meal where rice is cooked with lots of tomatoes, fresh herbs, whole spices & ground spices.',0.0,0,'Tue,Sun'),
 (31,'Zatar rice','Rice',12.0,25,1,'/project/uploads/menu_6a0b1befe2e598.39756076.jpg','A fragrant, aromatic Middle Eastern dish made by cooking rice (such as basmati or jasmine) with za''atar—a blend of toasted sesame seeds, sumac, and dried herbs like thyme and oregano',2.25,4,'Tue,Sun'),
 (32,'American chop suey','Noodles',15.9,23,1,'/project/uploads/menu_6a0b1c66d7f241.68825404.jpg','An American pasta casserole made with ground beef, macaroni, and a seasoned tomato sauce, found in the cuisine of New England and other regions of the United States',0.0,0,'Mon,Wed,Sun'),
 (33,'Buckwheat Noodles','Noodles',9.9,17,1,'/project/uploads/menu_6a0b1cb0d61bd8.84046145.webp','Thin, earthy noodles made from milled buckwheat and sometimes a bit of wheat flour for elasticity',5.0,1,'Wed,Sat'),
 (34,'Chow Mein','Noodles',15.5,24,1,'/project/uploads/menu_6a0b1cf5191ca8.39712500.jpg','Chinese stir-fried noodles with vegetables and sometimes meat or tofu',0.0,0,'Tue,Thu'),
